arguments.argument:
mybacktimer = 230+random(500)//This is the time chica stays in the office's left door when it is closed before leaving and moving back to Dining Area. Bonnie takes stays shorter time in the door than Chica.
backtimer = mybacktimer
mymovetime = 270+random(1100) //This is the time the animatronic takes to move from one room to another after leaving Show Stage. Change this to any value you want.
movetime = 500+random(2100)//This is the initial time the animatronic takes to move out of the Show Stage. Change this to any value you want.
//Variable "myroom" stands for the room the animatronic is located.
//myroom = 0 - Show Stage
//myroom = 1 - Dining Area
//myroom = 2 - Restrooms
//myroom = 3 - East Hall 1
//myroom = 4 - East Hall 2
//myroom = 5 - Office Door
//myroom = 6 - Unable to use lights/door buttons, and jumpscare when monitor is pulled up.
//Chica has a set path of moving to Show Stage > Dining Area > Restrooms > East Hall 1 > East Hall 2 > Office Door
//If you are going to edit the animatronic objects, be sure to edit as well objects that check the animatronic's variable "myroom" to work; those being the jumpscares and Draw event in obj_controller, obj_buttons_light, obj_buttons_doors, obj_door, and all camera objects.
myroom = 0
